package com.xqfx.requirements.requirement;
import java.time.LocalDate;
import java.time.LocalDateTime;
record RequirementResponse(Long id,String requesterName,String department,String title,RequirementType type,String content,Long systemId,RequirementSaveType saveType,RequirementStatus status,Long targetVersionId,String targetVersionName,LocalDate periodStartDate,LocalDate periodEndDate,LocalDateTime createdAt,LocalDateTime updatedAt,LocalDateTime submittedAt,LocalDateTime statusUpdatedAt,long recordVersion){static RequirementResponse from(RequirementEntity r){return new RequirementResponse(r.id(),r.requesterName(),r.department(),r.title(),r.type(),r.content(),r.system()==null?null:r.system().id(),r.saveType(),r.status(),r.targetVersion()==null?null:r.targetVersion().id(),r.targetVersion()==null?null:r.targetVersion().name(),r.periodStartDate(),r.periodEndDate(),r.createdAt(),r.updatedAt(),r.submittedAt(),r.statusUpdatedAt(),r.recordVersion());}}
